function RegisterSpinnerStyles(){if(FRegistered$9)return;FRegistered$9=!0;AddStyleBlock("\r\n\/* â\u201D\u20ACâ\u201D\u20AC Outer container: rotates continuously â\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20AC *\/\r\n\r\n.spinner {\r\n  position: relative;\r\n  width:    var(--spinner-size, 40px);\r\n  height:   var(--spinner-size, 40px);\r\n  animation: spinner-rotate var(--spinner-speed, 2.0s) infinite linear;\r\n}\r\n\r\n\/* â\u201D\u20ACâ\u201D\u20AC Dots: scale up\/down in alternation â\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20AC *\/\r\n\r\n.spinner-dot {\r\n  width:            60%;\r\n  height:           60%;\r\n  position:         absolute;\r\n  top:              0;\r\n  display:          inline-block;\r\n  border-radius:    50%;\r\n  background-color: var(--spinner-color, var(--primary-color, #6366f1));\r\n  animation:        spinner-bounce var(--spinner-speed, 2.0s) infinite ease-in-out;\r\n}\r\n\r\n.spinner-dot2 {\r\n  top:             auto;\r\n  bottom:          0;\r\n  animation-delay: calc(var(--spinner-speed, 2.0s) \/ -2);\r\n}\r\n\r\n\/* â\u201D\u20ACâ\u201D\u20AC Keyframes â\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20ACâ\u201D\u20AC *\/\r\n\r\n@keyframes spinner-rotate {\r\n  100% { transform: rotate(360deg); }\r\n}\r\n\r\n@keyframes spinner-bounce {\r\n  0%, 100% { transform: scale(0); }\r\n  50%       { transform: scale(1); }\r\n}\r\n\r\n")}
